window.docContents[171].resolve({"/3___-General-results-of-representation-theory/3___10___-Representations-of-tensor-products/Failure-of-Theorem-3___10___2-for-infinite-dimensional-representations/#Chapter3___Remark3___10___3":{"contents":"Remark 3.10.3. Part (ii) of the theorem typically fails for infinite dimensional representations; e.g. it fails when A is the Weyl algebra in characteristic zero. Part (i) may also fail. E.g. let A = B = V = W = \\mathbb{C}(x). Then (i) fails, as A \\otimes B is not a field.\n\n\n\n","context":"Introduction to Representation Theory\t3. General results of representation theory\t3.10. Representations of tensor products\tFailure of Theorem 3.10.2 for infinite dimensional representations","header":"Failure of Theorem 3.10.2 for infinite dimensional representations","id":"/3___-General-results-of-representation-theory/3___10___-Representations-of-tensor-products/Failure-of-Theorem-3___10___2-for-infinite-dimensional-representations/#Chapter3___Remark3___10___3"},"/3___-General-results-of-representation-theory/3___5___-Finite-dimensional-algebras/Semisimple-algebra/#Chapter3___Definition3___5___7":{"contents":"Definition 3.5.7. A finite dimensional algebra A is said to be semisimpleIn particular, the algebra A = 0 is semisimple, although it is not simple. Every representation of this algebra is zero, so it does not have any irreducible or indecomposable representations. It is, nevertheless, a direct sum of an (empty) collection of matrix algebras. if \\operatorname{Rad}(A) = 0.\n\n\n\n","context":"Introduction to Representation Theory\t3. General results of representation theory\t3.5. Finite dimensional algebras\tSemisimple algebra","header":"Semisimple algebra","id":"/3___-General-results-of-representation-theory/3___5___-Finite-dimensional-algebras/Semisimple-algebra/#Chapter3___Definition3___5___7"},"/3___-General-results-of-representation-theory/3___9___-Problems/Ext___1-for-polynomial-algebras-and-algebras-with-zero-multiplication/#Chapter3___Problem3___9___2":{"contents":"Problem 3.9.2. (a) Let A = \\mathbb{C}[x_1, \\ldots, x_n], and let V_a, V_b be 1-dimensional representations in which the elements x_i act by a_i and b_i, respectively (a_i, b_i \\in \\mathbb{C}). Find \\operatorname{Ext}^1(V_a, V_b) and classify 2-dimensional representations of A.\n\n(b) Let B be the algebra over \\mathbb{C} generated by x_1, \\ldots, x_n with the defining relations x_i x_j = 0 for all i, j. Show that for n > 1 the algebra B has infinitely many nonisomorphic indecomposable representations.\n\n\n\n","context":"Introduction to Representation Theory\t3. General results of representation theory\t3.9. Problems\tExt^1 for polynomial algebras and algebras with zero multiplication","header":"Ext^1 for polynomial algebras and algebras with zero multiplication","id":"/3___-General-results-of-representation-theory/3___9___-Problems/Ext___1-for-polynomial-algebras-and-algebras-with-zero-multiplication/#Chapter3___Problem3___9___2"},"/4___-Representations-of-finite-groups___-Basic-results/4___6___-Unitary-representations___-Another-proof-of-Maschke___s-theorem-for-complex-representations/Section-4___6___-Unitary-representations/#Introduction-to-Representation-Theory--4___-Representations-of-finite-groups___-Basic-results--4___6___-Unitary-representations___-Another-proof-of-Maschke___s-theorem-for-complex-representations--Section-4___6___-Unitary-representations":{"contents":"\n\n","context":"Introduction to Representation Theory\t4. Representations of finite groups: Basic results\t4.6. Unitary representations. Another proof of Maschke's theorem for complex representations","header":"Section 4.6: Unitary representations","id":"/4___-Representations-of-finite-groups___-Basic-results/4___6___-Unitary-representations___-Another-proof-of-Maschke___s-theorem-for-complex-representations/Section-4___6___-Unitary-representations/#Introduction-to-Representation-Theory--4___-Representations-of-finite-groups___-Basic-results--4___6___-Unitary-representations___-Another-proof-of-Maschke___s-theorem-for-complex-representations--Section-4___6___-Unitary-representations"}});
